package io.github.jesterportfolio.hearth.combat;
import io.github.jesterportfolio.hearth.quest.*;
import io.github.jesterportfolio.hearth.persistence.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.jesterportfolio.hearth.combat.CombatContent.*;
class DungeonPlayTest {
    static final String ID="public_dungeon",QUEST="dungeon_quest",NPC="guide";
    static QuestContent quest(){var area=new QuestContent.Area(0,6,63,68,0,6);return new QuestContent(QUEST,"공개 던전 의뢰",NPC,"안내원",3,64,3,0,6,63,68,0,6,QuestContent.CompletionMode.REPORT,QuestContent.StartMode.NPC,null,null,Map.of("offer","의뢰","accept","수락","active","던전 진행","report-ready","보고 대기","report","보고","completed","완료"),List.of(new QuestContent.Goal("보스 승리 확인",area,null,"dungeon:"+ID)));}
    static final class Repo implements QuestStore {final Map<String,Saved> rows=new HashMap<>();String failPlayer;CompletableFuture<Saved> read;String key(ServerProgressAccess.Context c){return c.storyRunId()+"/"+c.playerId();}public CompletionStage<Saved> readQuest(ServerProgressAccess.Context c,String id){return read!=null?read:CompletableFuture.completedFuture(rows.getOrDefault(key(c),new Saved(Phase.NOT_ACCEPTED,-1)));}public CompletionStage<Saved> advanceQuest(ServerProgressAccess.Context c,String id,Saved old,Phase next){if(Objects.equals(failPlayer,key(c))||!rows.getOrDefault(key(c),new Saved(Phase.NOT_ACCEPTED,-1)).equals(old))return CompletableFuture.failedFuture(new StorageFailure("test","DB_FAILURE"));var row=new Saved(next,old.revision()+1);rows.put(key(c),row);return CompletableFuture.completedFuture(row);}}
    static final class Person implements DungeonPlay.Actor {final ServerProgressAccess.Context ctx;final UUID world;Object token=new Object();boolean live=true,near=true,frozen;long generation=1;Person(ServerProgressAccess.Context ctx,UUID world){this.ctx=ctx;this.world=world;}public ServerProgressAccess.Context context(){return ctx;}public Object token(){return token;}public UUID world(){return world;}public long generation(){return generation;}public boolean current(){return live;}public boolean atEntry(){return near&&live;}public void freeze(boolean b){frozen=b;}}
    static final class F {final ServerProgressAccess access=new ServerProgressAccess();final UUID run=UUID.randomUUID(),other=UUID.randomUUID(),world=UUID.randomUUID();final Person p=new Person(access.forVerifiedServerLink(run,new UUID(1,1)),world),q=new Person(access.forVerifiedServerLink(run,new UUID(1,2)),world),b=new Person(access.forVerifiedServerLink(other,p.ctx.playerId()),UUID.randomUUID());final Repo repo=new Repo();final PersonalQuest quests=new PersonalQuest(repo,Set.of(QUEST),Runnable::run,()->{});final DungeonPlay.Definition definition=new DungeonPlay.Definition(ID,QUEST,NPC,new QuestContent.Area(0,6,63,68,0,6));List<DungeonPlay.Actor> people=new ArrayList<>(List.of(p,q));CompletableFuture<Void> save=CompletableFuture.completedFuture(null);boolean free=true,permitted=true;int starts;CombatAttempt started;final DungeonPlay play=new DungeonPlay(definition,quest(),quests,new DungeonPlay.Boundary(){public List<DungeonPlay.Actor> nearby(UUID id){return people;}public boolean available(UUID id){return free;}public boolean allowed(DungeonPlay.Actor a){return permitted;}public CompletionStage<Void> save(UUID id){return save;}public CombatAttempt start(List<DungeonPlay.Actor> selected){starts++;started=battle(selected);return started;}},Runnable::run,()->{});
        F(){repo.rows.put(repo.key(p.ctx),new QuestStore.Saved(QuestStore.Phase.ACTIVE,0));repo.rows.put(repo.key(q.ctx),new QuestStore.Saved(QuestStore.Phase.ACTIVE,0));}
        CombatAttempt battle(List<DungeonPlay.Actor> targets){return new CombatAttempt(run,world,1,CombatAttemptTest.content(Pool.SHARED,1,LocationMode.START),targets.stream().map(a->new CombatAttempt.Entrant(a.context(),a.token(),new Pose(world,3,64,3,0,0))).toList(),new CombatAttemptTest.Actors(),Runnable::run,()->{},()->100);}
        CompletionStage<CombatAttempt> enter(){return play.enter(p,NPC,()->true);}CombatAttempt boss(){var old=enter().toCompletableFuture().join();old.finish(CombatAttempt.Outcome.RETIRED);var boss=battle(new ArrayList<>(List.of(p,q)));play.changed(old,boss,false);boss.victory();return boss;}
    }
    static void failed(CompletionStage<?> f){assertThrows(CompletionException.class,()->f.toCompletableFuture().join());}
    @Test void onlyAcceptedActorsStartAndLookupDoesNotCreateRows(){var f=new F();f.repo.rows.remove(f.repo.key(f.q.ctx));var path=f.enter().toCompletableFuture().join();assertEquals(1,path.snapshot().difficultyPlayers());assertFalse(f.repo.rows.containsKey(f.repo.key(f.q.ctx)));assertEquals(1,f.starts);assertFalse(f.p.frozen);assertFalse(f.q.frozen);}
    @Test void unacceptedRequesterAndWrongNpcCannotStart(){var f=new F();f.repo.rows.remove(f.repo.key(f.p.ctx));failed(f.enter());failed(f.play.enter(f.p,"wrong",()->true));assertEquals(0,f.starts);}
    @Test void saveMustFinishAndDuplicateSharesOneStart(){var f=new F();f.save=new CompletableFuture<>();var a=f.enter();assertSame(a,f.enter());assertTrue(f.p.frozen);assertEquals(0,f.starts);assertFalse(f.play.barrier(f.run).toCompletableFuture().isDone());f.save.complete(null);a.toCompletableFuture().join();assertEquals(1,f.starts);assertFalse(f.p.frozen);}
    @Test void saveFailureHoldsAndReleasesOnlyItsLocks(){var f=new F();f.save=CompletableFuture.failedFuture(new StorageFailure("save","DB_FAILURE"));failed(f.enter());assertEquals(0,f.starts);assertFalse(f.p.frozen);assertFalse(f.q.frozen);failed(f.enter());failed(f.play.barrier(f.run));assertEquals(QuestStore.Phase.ACTIVE,f.repo.rows.get(f.repo.key(f.p.ctx)).phase());}
    @Test void quitRosterGenerationAndDialogueChangesPreventLateStart(){for(int k=0;k<4;k++){var f=new F();f.save=new CompletableFuture<>();var valid=new java.util.concurrent.atomic.AtomicBoolean(true);var work=f.play.enter(f.p,NPC,valid::get);if(k==0)f.p.live=false;if(k==1)f.people=new ArrayList<>(List.of(f.p));if(k==2)f.q.generation++;if(k==3)valid.set(false);f.save.complete(null);failed(work);assertEquals(0,f.starts);assertFalse(f.p.frozen);}}
    @Test void wrongRunAndRestrictedQuestCannotBeSelected(){var f=new F();f.people=List.of(f.p,f.b);failed(f.enter());assertEquals(0,f.starts);var g=new F();g.permitted=false;failed(g.enter());assertEquals(0,g.starts);}
    @Test void victoryAdvancesOwnAcceptedObjectiveOnceAndReportCompletes(){var f=new F();var boss=f.boss();var result=f.play.victory(boss,List.of(f.p,f.q));result.toCompletableFuture().join();assertSame(result,f.play.victory(boss,List.of(f.p,f.q)));assertEquals(new QuestStore.Saved(QuestStore.Phase.REPORT_READY,1),f.repo.rows.get(f.repo.key(f.p.ctx)));assertFalse(f.repo.rows.containsKey(f.repo.key(f.b.ctx)));var q=f.quests.open(f.p.ctx,QUEST,f.p.token,f.p::current).toCompletableFuture().join();f.quests.advance(q,QuestStore.Phase.COMPLETED).toCompletableFuture().join();assertEquals(2,q.saved().revision());}
    @Test void unrelatedAttemptCannotGrantOrChangeKnownBattle(){var f=new F();var path=f.enter().toCompletableFuture().join();var other=f.battle(List.of(f.p,f.q));other.victory();failed(f.play.victory(other,List.of(f.p,f.q)));assertThrows(IllegalStateException.class,()->f.play.changed(other,path,false));assertEquals(0,f.repo.rows.get(f.repo.key(f.p.ctx)).revision());}
    @Test void partialWriteFailureDoesNotClaimGroupSuccessOrDamageOtherRows(){var f=new F();var boss=f.boss();f.repo.failPlayer=f.repo.key(f.q.ctx);failed(f.play.victory(boss,List.of(f.p,f.q)));assertEquals(QuestStore.Phase.REPORT_READY,f.repo.rows.get(f.repo.key(f.p.ctx)).phase());assertEquals(new QuestStore.Saved(QuestStore.Phase.ACTIVE,0),f.repo.rows.get(f.repo.key(f.q.ctx)));assertTrue(f.play.lines(f.p).getFirst().contains("보류"));failed(f.play.barrier(f.run));}
    @Test void staleReadAndCloseDoNotStartBattle(){var f=new F();f.repo.read=new CompletableFuture<>();var read=f.repo.read;var work=f.enter();f.p.live=false;read.complete(new QuestStore.Saved(QuestStore.Phase.ACTIVE,0));failed(work);assertEquals(0,f.starts);var g=new F();g.save=new CompletableFuture<>();var saving=g.enter();g.play.close();g.save.complete(null);failed(saving);assertEquals(0,g.starts);}
    @Test void prototypeDoesNotGrantOfflinePlayersSuccess(){var f=new F();var old=f.enter().toCompletableFuture().join();old.finish(CombatAttempt.Outcome.RETIRED);var boss=f.battle(List.of(f.p,f.q));f.play.changed(old,boss,false);boss.disconnect(f.q.ctx,f.q.token,new Pose(f.world,3,64,3,0,0));boss.victory();f.play.victory(boss,List.of(f.p)).toCompletableFuture().join();assertEquals(0,f.repo.rows.get(f.repo.key(f.q.ctx)).revision());assertTrue(f.play.lines(f.p).stream().anyMatch(s->s.contains("오프라인")));}
    @Test void contentRequiresRegisteredUniqueObjectiveAndCheckpointLink(){var f=new F();var child=CombatAttemptTest.content(Pool.SHARED,1,LocationMode.START);var path=new Path(child,new FieldContent.Box(0,6,63,68,0,6),new Exit(new FieldContent.Point(3,64,3),0,0,1,List.of()));var combat=new CombatContent(ID,"공개 던전",20,2,3000,child.revival(),null,null,path);f.definition.validate(quest(),combat);assertThrows(IllegalArgumentException.class,()->new DungeonPlay.Definition("other",QUEST,NPC,f.definition.entry()).validate(quest(),combat));}
    @Test void completedAdmissionAndCreditHoldNeverReportAnotherSuccessfulEntry(){var f=new F();var boss=f.boss();failed(f.enter());f.repo.failPlayer=f.repo.key(f.p.ctx);failed(f.play.victory(boss,List.of(f.p,f.q)));failed(f.enter());assertEquals(1,f.starts);}

    @Test void unloadRejectsPendingAndHoldButReleasesOnlyClosedCompletedBattle(){var f=new F();f.save=new CompletableFuture<>();var entry=f.enter();assertThrows(IllegalStateException.class,()->f.play.unloaded(f.run));f.save.complete(null);var path=entry.toCompletableFuture().join();assertThrows(IllegalStateException.class,()->f.play.unloaded(f.run));path.finish(CombatAttempt.Outcome.RETIRED);f.play.unloaded(f.run);assertFalse(f.play.registered(path));var held=new F();held.save=CompletableFuture.failedFuture(new StorageFailure("db","FAILED"));failed(held.enter());assertThrows(IllegalStateException.class,()->held.play.unloaded(held.run));}

}
